#define MAX_TEXT_SIZE 4096

typedef struct { char *buffer; size_t pos; } SFILE;
static int objdump_sprintf (SFILE *f, const char *format, ...) {
  size_t n; va_list args; va_start (args, format);
  if (f->pos >= MAX_TEXT_SIZE){ return 0; }
  n = vsnprintf (f->buffer + f->pos, MAX_TEXT_SIZE - f->pos, format, args);
  va_end (args); f->pos += n; return n;
}
static void objdump_print_address (bfd_vma vma, struct disassemble_info *inf)
{ (*inf->fprintf_func) (inf->stream, "0x%x", (unsigned)vma); }

static void test_one(unsigned long instr, unsigned long mach) {
  char AssemblyText[MAX_TEXT_SIZE];
  struct disassemble_info disasm_info; SFILE s; bfd_byte buf[4];
  buf[0]=instr&0xff; buf[1]=(instr>>8)&0xff; buf[2]=(instr>>16)&0xff; buf[3]=(instr>>24)&0xff;
  memset(&disasm_info,0,sizeof disasm_info);
  init_disassemble_info (&disasm_info, stdout, (fprintf_ftype) fprintf);
  disasm_info.fprintf_func = (fprintf_ftype) objdump_sprintf;
  disasm_info.print_address_func = objdump_print_address;
  extern int buffer_read_memory (bfd_vma, bfd_byte *, unsigned int, struct disassemble_info *);
  disasm_info.read_memory_func = buffer_read_memory;
  disasm_info.display_endian = disasm_info.endian = BFD_ENDIAN_LITTLE;
  disasm_info.buffer = buf; disasm_info.buffer_vma = 0x1000;
  disasm_info.buffer_length = 4; disasm_info.stream = &s;
  s.buffer = AssemblyText; s.pos = 0;
  disasm_info.arch = bfd_arch_tic4x; disasm_info.mach = mach;
  print_insn_tic4x (0x1000, &disasm_info);
}

static void run(unsigned long instr, unsigned long mach) {
  unsigned long top = instr >> 16;
  if (top == 0x5070 || top == 0x1f70) return; // avoid setting DP (keeps state clean)
  test_one(instr, mach);
}

int main(int argc, char **argv) {
  unsigned long mach = (argc > 1) ? strtoul(argv[1],0,0) : 40;
  unsigned long total = 0;
  for (unsigned long i = 0; i < tic4x_num_insts; i++) {
    unsigned long op = tic4x_insts[i].opcode, mask = tic4x_insts[i].opmask;
    int varbits = 0; for (int b = 0; b < 32; b++) if (!((mask>>b)&1)) varbits++;
    if (varbits > 20) continue;
    unsigned long limit = 1ul << varbits;
    for (unsigned long v = 0; v < limit; v++) {
      // spread v into don't-care positions
      unsigned long instr = op & mask;
      unsigned long src = v;
      for (int b = 0; b < 32; b++) {
        if (!((mask>>b)&1)) { if (src & 1) instr |= (1ul<<b); src >>= 1; }
      }
      instr &= 0xfffffffful;
      run(instr, mach);
      total++;
    }
  }
  fprintf(stderr, "done mach=%lu total=%lu\n", mach, total);
  return 0;
}
